using namespace std;

const int N = 1e6 + 10;
int n, k, deg[N], h[N], q[N], a[N], dif[N];
bool del[N];
vector<int> g[N];

bool check(int x){
    if(x == 0) return n == k;
    int l = 0, r = 0, cnt = n;
    for(int i = 1; i <= n; i++){
        deg[i] = g[i].size();
        del[i] = 0;
        h[i] = 0;
        if(deg[i] == 1) q[r++] = i;
    }
    for(int i = 1; i <= x; i++){
        if(cnt <= k) return true;
        int ed = r;
        cnt -= ed-l;
        while(l < ed){
            int u = q[l++];
            del[u] = 1;
            for(int v: g[u]){
                if(del[v]) continue;
                h[v] = max(h[v], h[u]+1);
                if(--deg[v] == 1) q[r++] = v;
            }
        }
    }
    int m = cnt-k;
    if(m <= 0) return true;
    for(int u = 1; u <= n; u++){
        if(del[u] || deg[u] == 2) continue;
        for(int v: g[u]){
            if(del[v] || deg[v] != 2) continue;
            int p = u, cur = v, len = 0;
            while(deg[cur] == 2){
                a[++len] = cur;
                int nxt = 0;
                for(int w: g[cur]){
                    if(!del[w] && w != p){
                        nxt = w;
                        break;
                    }
                }
                p = cur;
                cur = nxt;
            }
            if(u > cur || len < m) continue;
            int lim = len-m+1;
            fill(dif+1, dif+lim+2, 0);
            for(int j = 1; j <= len; j++){
                int d = x-h[a[j]];
                int L = max(1, j+d-m+1);
                int R = min(lim, j-d);
                if(L <= R){
                    dif[L]++;
                    dif[R+1]--;
                }
            }
            int sum = 0;
            for(int s = 1; s <= lim; s++){
                sum += dif[s];
                if(!sum) return true;
            }
        }
    }
    return false;
}

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);
    int c, t;
    cin >> c >> t;
    while(t--){
        cin >> n >> k;
        for(int i = 1; i <= n; i++) g[i].clear();
        for(int i = 1; i < n; i++){
            int u, v;
            cin >> u >> v;
            g[u].push_back(v);
            g[v].push_back(u);
        }
        int l = 0, r = n;
        while(l < r){
            int mid = (l+r)/2;
            if(check(mid)) r = mid;
            else l = mid+1;
        }
        cout << l << endl;
    }
    return 0;
}
