#include<iostream>
#include<vector>

using namespace std;

const int N = 1e6 + 10;
int c, t, n, k, u, v, cnt, tin[N], in[N], fa[N], sz[N], dep[N];
vector<int> g[N], stk, stk2, G[N]; bool tg[N], vis[N], fd[N];

int fr(int u){
	if(u == fa[u]) return u;
	return fa[u] = fr(fa[u]);
}

void mg(int u, int v){
	u = fr(u); v = fr(v);
	if(u == v) return;
	fa[u] = v; sz[v] += sz[u];
}

void find_line2(int u, vector<int> & res){
//	cout << "Find2:" << u << '\n';
	fd[u] = 1; res.push_back(u);
	for(int v: g[u]){
		if(fd[v] || fr(u) != fr(v)) continue;
		find_line2(v, res);
	}
}

void find_line(int u, vector<int> & res){
//	cout << "Find:" << u << '\n';
	vector<int> res1, res2; fd[u] = 1;
	bool fg = 1;
	for(int v: g[u]){
		if(fr(u) != fr(v)) continue;
//		cout << fr(u) << ' ' << fr(v) << '\n';
//		cout << "To:" << v << '\n';
		if(fg){
			find_line2(v, res1);
			fg = 0;
		}
		else{
			find_line2(v, res2);
		}
	}
	for(int i = res2.size()-1; i >= 0; i--) res.push_back(res2[i]);
	res.push_back(u);
	for(int i: res1) res.push_back(i);
}

bool check(int x){
	if(x == 0) return n == k;
	cnt = n; stk.clear(); stk2.clear();
	for(int i = 1; i <= n; i++){
		tin[i] = in[i]; G[i].clear(); sz[i] = 1;
		if(in[i] == 1) stk2.push_back(i);
		vis[i] = dep[i] = fd[i] = tg[i] = 0; fa[i] = i;
	}
//	cout << x << '\n';
	for(int i = 1; i <= x; i++){
		stk = stk2; stk2.clear();
		for(int u: stk){
			vis[u] = 1; cnt--;
			for(int v: g[u]){
				dep[v] = max(dep[v], dep[u]+1); 
				if(--tin[v] == 1) stk2.push_back(v);
			}
		}
	}
	if(cnt <= k) return 1;
//	cout << cnt << '\n';
	for(int i = 1; i <= n; i++){
		if(vis[i] == 0 && tin[i] == 2) tg[i] = 1;
	}
//	cout << x << '\n';
//	for(int i = 1; i <= n; i++) cout << tg[i] << ' ';
//	cout << '\n';
//	for(int i = 1; i <= n; i++) cout << dep[i] << ' ';
//	cout << '\n';
	for(int i = 1; i <= n; i++){
		for(int j: g[i]){
			if(tg[i] && tg[j]) mg(i, j);
		}
	}
//	for(int i = 1; i <= n; i++) cout << fr(i) << ' ';
//	cout << '\n'; 
	for(int i = 1; i <= n; i++){
		if(tg[i]){
//			cout << i << ' ' << fr(i) << '\n'; 
			G[fr(i)].push_back(i); 
		}
	}
	for(int i = 1; i <= n; i++){
		if(fr(i) == i && tg[i]){
			int len = G[i].size();
			vector<int> ls, del;
			ls.push_back(0);
			find_line(i, ls);
			for(int j = 0; j <= len+1; j++) del.push_back(0);
			for(int j = 1; j <= len; j++){
				int l = max(0, j+(x-dep[ls[j]])-(cnt-k)+1), r = min(len, j-(x-dep[ls[j]]))+1;
				if(l < r) del[l]++, del[r]--;
			}
			for(int j = 1; j <= len; j++){
				del[j] += del[j-1];
				if(del[j] == 0) return 1;
			}
		}
	}
//	cout << mx << '\n';
	return 0;
}

int main(){
	ios::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
//	freopen("pre/hub3.in", "r", stdin);
	cin >> c >> t;
	while(t--){ 
		cin >> n >> k;
		for(int i = 1; i < n; i++){
			cin >> u >> v;
			g[u].push_back(v);
			g[v].push_back(u);
			in[u]++; in[v]++;
		}
		int l = 0, r = n, ans = 0;
		while(l <= r){
			int mid = (l + r) / 2;
			if(check(mid)){
				ans = mid;
				r = mid-1;
			}
			else l = mid+1;
		}
		cout << ans << '\n';
		for(int i = 1; i <= n; i++){
			in[i] = 0;
			g[i].clear();
		}
	}
	return 0;
}
