#include <bits/stdc++.h>
using namespace std;

const int N = 1e6 + 10;
int n, k, deg[N], adj[N], q[N], id[N], fa[N], lay[N];
int h[N], a[N], dif[N];

inline int gc(){
    static char buf[1 << 16];
    static int p = 0, len = 0;
    if(p == len){
        len = fread(buf, 1, sizeof(buf), stdin);
        p = 0;
        if(!len) return EOF;
    }
    return buf[p++];
}

int read(){
    int x = 0, c = gc();
    while(c != EOF && c <= ' ') c = gc();
    while(c >= '0' && c <= '9'){
        x = x*10+c-'0';
        c = gc();
    }
    return x;
}

void init(){
    int r = 0;
    for(int u = 1; u <= n; u++){
        if(deg[u] == 1){
            q[++r] = u;
            id[u] = r;
            lay[r] = 1;
        }
    }
    for(int i = 1; i < n; i++){
        int u = q[i], v = adj[u];
        fa[i] = v;
        adj[v] ^= u;
        if(--deg[v] == 1){
            q[++r] = v;
            id[v] = r;
            lay[r] = lay[i]+1;
        }
    }
    // 之后全部使用出队编号，每条边为 (i, fa[i])，且 fa[i] > i。
    for(int i = 1; i < n; i++) fa[i] = id[fa[i]];
    fa[n] = 0;
}

bool check(int x){
    int cut = upper_bound(lay+1, lay+n+1, x)-lay-1;
    int m = n-cut-k;
    if(m <= 0) return true;
    if(m > 2*x) return false;

    // i 被剥掉而 fa[i] 保留时，这条挂枝的高度为 lay[i]。
    // 按 lay 非降序覆盖，最后写入的就是最大值。
    fill(h+cut+1, h+n+1, 0);
    for(int i = 1; i <= cut; i++){
        int p = fa[i];
        if(p > cut) h[p] = lay[i];
    }

    // 剩余点恰好是 [cut+1, n]，父边可以直接保留。
    for(int i = cut+1; i <= n; i++){
        deg[i] = 1;
        adj[i] = fa[i];
    }
    deg[n] = 0;
    for(int i = cut+1; i < n; i++){
        int p = fa[i];
        deg[p]++;
        adj[p] ^= i;
    }

    for(int i = cut+1; i < n; i++){
        int u = i, v = fa[i];
        if(deg[u] == 2 && deg[v] != 2) swap(u, v);
        if(deg[u] == 2 || deg[v] != 2) continue;

        // 从链外的 u 出发，沿度二点走完整条链。
        int len = 0;
        while(deg[v] == 2){
            a[++len] = x-h[v];
            deg[v] = -1;
            int w = adj[v]^u;
            u = v;
            v = w;
        }
        if(len < m) continue;

        int lim = len-m+1;
        fill(dif+1, dif+lim+2, 0);
        for(int j = 1; j <= len; j++){
            int l = max(1, j+a[j]-m+1);
            int r = min(lim, j-a[j]);
            if(l <= r) dif[l]++, dif[r+1]--;
        }
        int sum = 0;
        for(int j = 1; j <= lim; j++){
            sum += dif[j];
            if(!sum) return true;
        }
    }
    return false;
}

int main(){
    read();
    int t = read();
    while(t--){
        n = read(); k = read();
        fill(deg+1, deg+n+1, 0);
        fill(adj+1, adj+n+1, 0);
        for(int i = 1; i < n; i++){
            int u = read(), v = read();
            deg[u]++; deg[v]++;
            adj[u] ^= v; adj[v] ^= u;
        }
        if(n == k){
            puts("0");
            continue;
        }
        init();
        int l = 1, r = lay[n-k];
        while(l < r){
            int mid = (l+r)/2;
            if(check(mid)) r = mid;
            else l = mid+1;
        }
        printf("%d\n", l);
    }
    return 0;
}
```

